export const orderLabels={prepared:'Klar til PF',gateway_accepted:'Teknisk modtaget · afventer PF',confirmed:'Ordre bekræftet af PF',awaiting_proof:'Afventer korrektur fra PF',proof_received:'Korrektur klar',approval_pending_pf:'Kunden har godkendt',revision_requested:'Ændringer ønsket',approval_recorded:'Produktion godkendt hos PF',processing:'PF behandler ordren',partially_shipped:'Delvist afsendt',shipped:'Afsendt',needs_attention:'Kræver afklaring',needs_reconciliation:'Afstem med PF',cancelled:'Annulleret'};
export const dateTime=value=>value&&!Number.isNaN(Date.parse(value))?new Date(value).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
export function orderKind(order={},checkout={}){if(order.adminTest||checkout?.adminTest)return 'Intern test';if(order.isTest||order.gatewayPayload?.Header?.isTest)return 'PF-test';if(checkout?.adminPilot)return 'Rigtig testordre';return 'Kundeordre';}
export function shipmentNextStep(order,checkout,mails=[]){
 const tasks=[];
 if(checkout?.status==='authorized')tasks.push('Hæv betalingen, når alle varer på kundeordren er bekræftet afsendt.');
 else if(checkout?.status!=='paid')tasks.push('Afklar betaling: '+paymentLabel(checkout)+'.');
 const deliveries=order.shipment?.deliveries||[];
 if(!deliveries.length||deliveries.some(d=>!d.trackingDetails?.some(t=>t.trackingId&&t.trackingURL)))tasks.push('Kontrollér afsendelse og manglende trackingoplysninger.');
 if(!deliveries.length||deliveries.some(d=>!d.key||!mails.some(m=>m.orderId===order.id&&m.deliveryKey===d.key&&m.status==='sent')))tasks.push('Gennemgå forsendelsesmail og afsendelsesstatus under Historik.');
 return tasks.length?['Smerch',tasks.join(' ')]:['Afsluttet','Alle varer er afsendt, betalingen er hævet, og forsendelsesmails er sendt.'];
}
export function nextStep(order,checkout,mails=[]){if(order.adminTest||order.isTest||order.gatewayPayload?.Header?.isTest)return ['Test','Testordre · må ikke frigives til produktion.'];switch(order.status){case 'proof_received':return order.proof?.customer?['Kunden','Afventer kundens svar på korrekturen.']:['Smerch','Gennemgå korrekturen og send den til kunden.'];case 'approval_pending_pf':return order.decision?.delivery?.reference?['PF','Afventer PF’s bekræftelse af godkendelsen.']:['Smerch','Godkend hos PF og registrér PF’s bekræftelse på ordren.'];case 'revision_requested':return order.decision?.delivery?.reference?['PF','Afventer en ny korrektur.']:['Smerch','Send kundens ændringer til PF.'];case 'partially_shipped':return ['PF','Delleverance registreret. Følg tracking og afvent de resterende varer.'];case 'processing':case 'approval_recorded':case 'confirmed':return ['PF','Afventer produktion og afsendelse'+(order.expectedShipDate?' · forventet '+dateTime(order.expectedShipDate):'.')];case 'shipped':return shipmentNextStep(order,checkout,mails);case 'cancelled':return ['Afsluttet','Ordren er annulleret.'];case 'prepared':return ['Smerch','Ordren er endnu ikke sendt til PF.'];case 'needs_attention':case 'needs_reconciliation':return ['Smerch','Kontrollér hændelsesloggen og afklar sagen med PF.'];case 'gateway_accepted':return ['PF','Teknisk kvittering modtaget. Afventer PF’s ordrebekræftelse.'];default:return ['PF','Afventer næste opdatering fra PF.'];}}
export function paymentLabel(checkout){if(!checkout)return 'Ingen betaling tilknyttet';return {authorized:'Reserveret · ikke hævet',paid:'Hævet',cancelled:'Annulleret',awaiting_payment:'Afventer betaling',authorization_expired:'Reservation udløbet',capture_reconciliation:'Hævning skal afstemmes',expired:'Betalingslink udløbet'}[checkout.status]||checkout.status;}
export const eventLabels={prepared:'Ordre klargjort',submitting:'Sender til PF',gateway_accepted:'Teknisk kvittering fra PF',pf_confirmation:'PF-ordrebekræftelse modtaget',pf_status:'Status opdateret fra PF',proof_received:'Korrektur modtaget',proof_published:'Korrektur sendt til kunden',customer_decision:'Kunden har svaret',approval_delivery:'Beslutning sendt til PF',external_approval:'PF har bekræftet godkendelsen',shipped:'Afsendelse registreret'};

// A real pilot checkout belongs in operations; only non-production tests are hidden.
export function isTestOrder(order={},checkout={}){return ['Intern test','PF-test'].includes(orderKind(order,checkout));}
